// Plain takvim tarihi biçimlendirme yardımcıları.
// Tüm tarih okuma/biçimlendirme saat dilimi kaymasına karşı güvenli olması için
// helpers/plainDate.ts üzerinden yapılır (bkz. oradaki açıklama).
import { formatPlainDate, parsePlainDate } from "./plainDate";

/**
 * input date format: 2024-05-09
 * output date format: May 09, 2024
 * */
function FormatDate(inputDate: string | Date) {
    if (!inputDate) {
        return null;
    }
    return formatPlainDate(inputDate, { month: "short", day: "2-digit", year: "numeric" });
}
export default FormatDate;

export function FormatDateLong(stringDate: string) {
    return formatPlainDate(stringDate, {
        weekday: "long",
        month: "long",
        day: "numeric",
        year: "numeric",
    });
}

/**
 * input date format: Thu May 16 2024 00:00:00 GMT+0300 (UTC+03:00)
 * output date format: 2024-05-16
 * */
export function formatDateShort(dateObject: any, inverse: boolean = false) {
    const year = dateObject.getFullYear();
    const month = String(dateObject.getMonth() + 1).padStart(2, '0');
    const day = String(dateObject.getDate()).padStart(2, '0');

    if (inverse) {
        return `${day}-${month}-${year}`;
    }
    return `${year}-${month}-${day}`;
}

/**
 * input date format: 2024-05-16
 * output date format: Thu May 16 2024 00:00:00 GMT+0300 (UTC+03:00)
 * */
export function formatExtraLong(stringDate: string, nbMonthsToAdd: number = 0) {
    const dateYear = parseInt(stringDate.substring(0, 4));
    const dateMonth = parseInt(stringDate.substring(5, 7)) + nbMonthsToAdd - 1; //  -1, month index starts from 0
    const dateDay = parseInt(stringDate.substring(8, 10));

    return new Date(dateYear, dateMonth, dateDay);
}
