/**
 * Takvim tarihi (plain date) yardımcıları.
 *
 * API'den gelen tur tarihleri ("2026-09-04") saat dilimi TAŞIMAZ — bunlar bir "an" değil,
 * duvar takvimindeki gündür. JS'te `new Date("2026-09-04")` bu string'i UTC gece yarısı
 * sayar; ardından `getDate()/toLocaleString` yerel saat dilimine göre okununca UTC'nin
 * batısındaki (negatif offset) kullanıcılarda gün BİR GERİ kayar (Sep 4 → Sep 3).
 *
 * Çözüm: tarihi sayısal parçalardan YEREL gece yarısı olarak kur (bu kurucu UTC uygulamaz),
 * böylece gün her saat diliminde korunur. API hangi günü gönderdiyse ekranda o görünür.
 */

/** "2026-09-04" (veya ISO datetime) → yerel gece yarısı Date; Date verilirse aynen döner. */
export function parsePlainDate(value: string | Date): Date {
  if (value instanceof Date) return value;
  const [y, m, d] = String(value).slice(0, 10).split("-").map(Number);
  return new Date(y, (m || 1) - 1, d || 1);
}

/**
 * Plain tarihi saat dilimi kaymasına sokmadan biçimlendirir.
 * Varsayılan çıktı: "Sep 4, 2026".
 */
export function formatPlainDate(
  value: string | Date,
  opts: Intl.DateTimeFormatOptions = { month: "short", day: "numeric", year: "numeric" },
  locale = "en-US",
): string {
  return new Intl.DateTimeFormat(locale, opts).format(parsePlainDate(value));
}

/** Plain tarihe gün ekler, yine plain (yerel) Date döner — toISOString round-trip'i YOK. */
export function addPlainDays(value: string | Date, days: number): Date {
  const d = parsePlainDate(value);
  d.setDate(d.getDate() + days);
  return d;
}
